                result.push_back(_vexList[(i+start)%_vexNum].v);
                visited[(i+start)%_vexNum] = true;
            } else continue;
            while (!queue.empty()) {
                auto ptr = _vexList[queue.pop()].next;
                if (ptr) {
                    while (ptr->next != nullptr) {
                        if (!visited[ptr->adjVex]) {
