    options = {{"-student", "1"}, {"-mentor", "1000"}};
    EXPECT_EQ(people_management->mentor(target, options), RECORD_NOT_EXISTS);

    target = "assign";
    options = {{"-student", "1"}, {"-mentor", "2"}};
